      else if (top && d > 0) b = MIX[Math.floor(hash(x, z, y + 11) * MIX.length)];
      else if (top) b = "stone";
      else b = hash(x, z, y) < 0.25 ? "andesite" : hash(x, z, y + 5) < 0.12 ? "tuff" : "stone";
