  door(g, 51, 17, 36, "west");
  g.set(51, 19, 36, "smooth_sandstone");
  door(g, 74, 26, 31, "north");
  // arrow slits spiralling up the gate towers
  for (const [cx, cz] of GTOWERS) spiralSlits(g, cx, cz, 4, 15, 34, 3, 80);
}

